mapper.select:
SELECT *
FROM lunaerp_finance_payment_apply
WHERE id = #{id}
  AND deleted = 1
  AND approval_status IN ('PENDING', 'DRAFT')
  AND tenant_id = #{tenantId}

mapper.update:
UPDATE lunaerp_finance_payment_apply
SET deleted = 0,
    approval_status = 'PENDING',
    updater = #{updater},
    update_time = #{now}
WHERE id = #{id}
  AND deleted = 1
  AND approval_status IN ('PENDING', 'DRAFT')
  AND tenant_id = #{tenantId}

mapper.delete:
DELETE FROM lunaerp_finance_payment_apply
WHERE id = #{id}
  AND deleted = 1
  AND approval_status IN ('PENDING', 'DRAFT')
  AND tenant_id = #{tenantId}

mapper.select:
SELECT COUNT(1)
FROM lunaerp_finance_payment_ref
WHERE ref_type = 'PAY_APPLY'
  AND ref_id = #{id}
  AND deleted = 0
  AND tenant_id = #{tenantId}

SELECT COALESCE(SUM(r.allocate_amount), 0)
FROM lunaerp_finance_payment_ref r
JOIN lunaerp_finance_payment_apply a ON r.ref_id = a.id
WHERE a.supplier_id = #{supplierId}
  AND a.apply_type = #{applyType}
  AND r.ref_type = 'PAY_APPLY'
  AND r.deleted = 0
  AND a.deleted = 0
  AND a.tenant_id = #{tenantId}
